package com.zipai.web;
import com.zipai.domain.User;import com.zipai.repository.UserRepository;import com.zipai.service.*;import jakarta.servlet.http.HttpSession;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.*;
@RestController @RequestMapping("/api/auth/verification") public class VerificationController{private final VerificationService verification;private final AuthService auth;private final UserRepository users;@Value("${zipai.verification.expose-code:false}")boolean exposeCode;public VerificationController(VerificationService v,AuthService a,UserRepository u){verification=v;auth=a;users=u;}
 @PostMapping("/send")Map<String,Object> send(@RequestBody Map<String,Object>b,HttpSession s){String purpose=t(b,"purpose"),channel=t(b,"channel"),destination=t(b,"destination");User u=purpose.equals("password_reset")?users.findByEmailIgnoreCase(destination).orElse(null):auth.current(s);if(purpose.equals("password_reset")&&u==null)return Map.of("success",true);String code=verification.send(purpose,channel,destination,u);Map<String,Object> result=new LinkedHashMap<>();result.put("success",true);result.put("expiresInSeconds",300);if(exposeCode)result.put("demoCode",code);return result;}
 @PostMapping("/verify")Map<String,Object> verify(@RequestBody Map<String,Object>b){verification.verify(t(b,"purpose"),t(b,"channel"),t(b,"destination"),t(b,"code"));return Map.of("success",true);}
 @PostMapping("/reset-password")Map<String,Object> reset(@RequestBody Map<String,Object>b){String email=t(b,"email");if(!verification.consumeVerified("password_reset","email",email))throw new ResponseStatusException(FORBIDDEN,"이메일 인증을 먼저 완료해 주세요.");auth.resetPassword(email,t(b,"newPassword"));return Map.of("success",true);}
 private static String t(Map<String,Object>b,String k){return String.valueOf(b.getOrDefault(k,"")).trim();}}
